/**
 * RemappingImport — generated by `remotion-ui import-ae` from remapping.json (Bodymovin 5.5.7).
 * 512×512 at 60 fps, 180 frames.
 *
 * Plain data on top of `ae-motion`: keyframe frames are this composition's
 * frames, speed is units per second, scale is a factor and opacity is 0–1.
 * Edit a key, a colour or a layer's inPoint/outPoint/startTime and re-render.
 */
import { AeComposition, AeLayer, precompLayer } from "@/remotion/lib/ae-import";
import { CompositionPrecomp } from "./composition";

/** "Composition" — precomp layer (CompositionPrecomp), frames 0–180. */
const compositionLayer = precompLayer({
  name: "Composition",
  inPoint: 0,
  outPoint: 180,
  transform: { scale: [0.5, 0.5] },
  width: 512,
  height: 512,
});

export const Composition = () => (
  <AeLayer layer={compositionLayer}>
    <CompositionPrecomp />
  </AeLayer>
);

/** "Remapped" — precomp layer (CompositionPrecomp), frames 0–180. */
const remappedLayer = precompLayer({
  name: "Remapped",
  inPoint: 0,
  outPoint: 180,
  transform: { anchor: [512, 512], position: [512, 512], scale: [0.5, 0.5] },
  width: 512,
  height: 512,
  timeRemap: [
    { frame: 0, value: 0, interpolation: "linear" },
    { frame: 30, value: 180, interpolation: "linear" },
    { frame: 60, value: 90, interpolation: "linear" },
    { frame: 180, value: 180 },
  ],
});

export const Remapped = () => (
  <AeLayer layer={remappedLayer}>
    <CompositionPrecomp />
  </AeLayer>
);

/** The composition. Layers are listed bottom of the AE timeline first — later ones draw on top. */
export const RemappingImport = () => (
  <AeComposition width={512} height={512} fps={60}>
    <Remapped />
    <Composition />
  </AeComposition>
);

/** Register with `<Composition {...config} />`; `remotion-ui import-ae` adds it to Root.tsx for you. */
export const remappingImportComposition = {
  id: "RemappingImport",
  component: RemappingImport,
  durationInFrames: 180,
  fps: 60,
  width: 512,
  height: 512,
};
